import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/var/lib/app/users.db')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(token):
    """Verify HMAC-based session token"""
    if not token:
        return None
    parts = token.split('.')
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return payload
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering by role and partial name match."""
    auth = request.headers.get('X-Auth-Token')
    session = verify_session(auth)
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    username_filter = request.args.get('name', '')
    role_filter = request.args.get('role', '')
    sort_by = request.args.get('sort', 'username')

    # Build query with filters
    conditions = []
    params = []

    if username_filter:
        conditions.append(f"username LIKE '%{username_filter}%'")

    if role_filter:
        conditions.append("role = ?")
        params.append(role_filter)

    where_clause = " WHERE " + " AND ".join(conditions) if conditions else ""

    # Whitelist sort columns
    allowed_sorts = ['username', 'email', 'role', 'id']
    if sort_by not in allowed_sorts:
        sort_by = 'username'

    query = f"SELECT id, username, email, role FROM users{where_clause} ORDER BY {sort_by} LIMIT 50"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
                   ('search', f'name={username_filter} role={role_filter}'))
        db.commit()
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

    return jsonify({'users': [dict(r) for r in results]})

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    auth = request.headers.get('X-Auth-Token')
    session = verify_session(auth)
    if not session:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute("SELECT id, username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
